 var st=document.createElement('style');st.id='xwvid-css';st.textContent=".vdsec{border:1px solid rgba(201,164,92,.45)!important;border-radius:14px;padding:12px 14px!important;margin:10px 0!important;background:linear-gradient(160deg,rgba(201,164,92,.09),rgba(201,164,92,.02))}\n.vdh{display:flex;flex-wrap:wrap;align-items:baseline;gap:4px 10px;margin:0 0 10px}\n.vdh b{font-size:15px;letter-spacing:2px;color:#E8CD8A}\n.vdh span{font-size:13px;color:#B8AC94}\n.vdall{display:inline-block;margin-top:4px;font-size:14px;color:#E8CD8A;text-decoration:none;border-bottom:1px dashed rgba(232,205,138,.6)}\n.xvv{display:grid;grid-template-columns:minmax(0,1fr);gap:8px;margin:0 0 14px;padding:0 0 12px;border-bottom:1px solid rgba(201,164,92,.18)}\n.xvv:last-of-type{border-bottom:0}\n@media(min-width:760px){.xvv{grid-template-columns:minmax(0,46%) minmax(0,1fr);gap:14px}}\n.xvy{position:relative;aspect-ratio:16/9;border-radius:10px;overflow:hidden;background:#000}\n.xvy iframe{position:absolute;inset:0;width:100%;height:100%;border:0}\n.xvyp{all:unset;cursor:pointer;position:absolute;inset:0;display:block}\n.xvyp img{width:100%;height:100%;object-fit:cover;display:block;opacity:.9}\n.xvyb{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);filter:drop-shadow(0 2px 6px rgba(0,0,0,.6))}\n.xvyt{position:absolute;left:8px;top:8px;background:rgba(0,0,0,.75);color:#F2D89A;font-size:13px;padding:3px 8px;border-radius:6px}\n.xvyl{position:absolute;right:8px;bottom:8px;background:rgba(0,0,0,.8);color:#fff;font-size:12px;padding:2px 6px;border-radius:4px}\n.xvm{min-width:0}\n.xvt{display:block;font-size:15.5px;line-height:1.45;color:#F1E7D2}\n.xvi{display:block;font-size:13px;color:#A99E88;margin:3px 0 6px}\n.xvn,.xvs{font-size:14.5px;line-height:1.65;color:#DCD2BE;margin:4px 0}\n.xvs{color:#B8AC94}\n.xvtag{font-style:normal;display:inline-block;font-size:12px;padding:1px 7px;margin-right:6px;border-radius:999px;border:1px solid rgba(201,164,92,.6);color:#E8CD8A;vertical-align:1px}\n.xvtag.me{background:#C9A45C;color:#17120B;border-color:#C9A45C}\n.xvcs{display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin:6px 0}\n.xvcs span{font-size:13px;color:#A99E88}\n.xvc{all:unset;cursor:pointer;font-size:13px;padding:4px 9px;border-radius:999px;border:1px solid rgba(201,164,92,.38);color:#E8CD8A;background:rgba(255,255,255,.03)}\n.xvc:active,.xvc:hover{background:rgba(201,164,92,.18)}\n.xvyt2{font-size:13px;color:#A99E88}\n.xvseen{font-style:normal;font-size:12px;margin-left:8px;padding:1px 7px;border-radius:999px;border:1px solid #4A4030;color:#6F6555}\n.xvseen::before{content:'○ '}\n.xvseen.on{border-color:#7FD1B5;color:#7FD1B5}.xvseen.on::before{content:'✓ '}\n.xvkb{margin:10px 0 16px}\n.xvkbv{border:1px solid rgba(201,164,92,.3);border-radius:12px;padding:10px 12px;margin:10px 0;background:rgba(201,164,92,.04)}\n.xvak{display:inline-block;font-size:12px;letter-spacing:2px;color:#C9A45C;margin-bottom:6px}\n/* 動畫 */\n.xva{border:1px solid rgba(201,164,92,.5);border-radius:14px;padding:12px;margin:10px 0 14px;color:#EDE6D6;max-width:760px}\n.xvah{display:flex;flex-direction:column;gap:2px;margin-bottom:8px}\n.xvah b{font-size:17px;color:#F2D89A;line-height:1.35}\n.xvah small{font-size:13px;color:#A99E88}\n.xvst{position:relative;aspect-ratio:16/10;border-radius:10px;overflow:hidden}\n.xvsl,.xvsimg,.xvssvg{position:absolute;inset:0}\n.xvsimg img{width:100%;height:100%;object-fit:cover;display:block}\n.xvsimg.kb0 img{animation:xvkb0 9s ease-out both}\n.xvsimg.kb1 img{animation:xvkb1 9s ease-out both}\n@keyframes xvkb0{from{transform:scale(1)}to{transform:scale(1.12) translate(-2%,-1%)}}\n@keyframes xvkb1{from{transform:scale(1.12) translate(2%,1%)}to{transform:scale(1)}}\n.xvsimg,.xvssvg{animation:xvfade .5s ease both}\n@keyframes xvfade{from{opacity:0}to{opacity:1}}\n.xvssvg{display:flex;align-items:center;justify-content:center;background:radial-gradient(120% 90% at 50% 10%,#241D15,#0A0806)}\n.xvssvg svg{width:100%;height:100%}\n.xvsn{position:absolute;right:10px;top:10px;font-size:13px;background:rgba(0,0,0,.65);color:#F2D89A;padding:2px 8px;border-radius:6px}\n.xvbig{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:64px;height:64px;border-radius:50%;border:2px solid #C9A45C;background:rgba(10,8,6,.75);color:#F2D89A;font-size:24px;cursor:pointer}\n.xvbar{height:4px;background:#2E271E;border-radius:2px;margin:8px 0 6px;overflow:hidden}\n.xvbar i{display:block;height:100%;width:0;background:#C9A45C}\n.xvdots{display:flex;flex-wrap:wrap;gap:5px;margin:4px 0 8px}\n.xvdots button{all:unset;cursor:pointer;min-width:26px;height:26px;text-align:center;line-height:26px;font-size:13px;border-radius:50%;border:1px solid #4A4030;color:#A99E88}\n.xvdots button.done{border-color:#7A6640;color:#C9A45C}\n.xvdots button.on{background:#C9A45C;color:#17120B;border-color:#C9A45C;font-weight:700}\n.xvcap{min-height:92px}\n.xvct{display:block;font-size:18px;color:#F2D89A;margin-bottom:4px}\n.xvcx{font-size:15px;line-height:1.65;margin:0 0 4px;color:#E6DCC8}\n.xvck{font-size:14px;color:#E8CD8A;margin:0}\n.xvck:empty{display:none}\n.xvctl{display:flex;gap:8px;margin-top:8px}\n.xvctl button,.xvre{all:unset;cursor:pointer;flex:1;text-align:center;padding:9px 6px;border-radius:10px;border:1px solid rgba(201,164,92,.4);font-size:14px;color:#E8CD8A;background:rgba(255,255,255,.03)}\n.xvctl .xvpp{flex:1.3;background:rgba(201,164,92,.16)}\n.xvend{margin-top:10px;border-left:3px solid #C9A45C;padding:8px 12px;background:rgba(201,164,92,.08);border-radius:6px}\n.xvend b{color:#F2D89A;font-size:14px}.xvend p{margin:4px 0 8px;font-size:15px;line-height:1.6}\n.xvre{display:inline-block;flex:none;padding:6px 14px}\n.xvsrc{font-size:12px;color:#8A8070;margin:8px 0 0;line-height:1.5}\n.xs-t{font-size:20px;fill:#F2D89A;font-weight:700}\n.xs-s{font-size:14px;fill:#CFC4AE}\n.xs-ax{font-size:11px;fill:#A99E88}\n.xs-lb{font-size:13px;font-weight:700}\n.xg-abv{font-size:40px;font-weight:800;fill:#F2D89A}\n.xs-fo{font-size:13.5px;line-height:1.45;color:#E6DCC8}\n.xs-g{transition:fill .8s}\n.xs-m{transition:transform 1s cubic-bezier(.3,.7,.3,1)}\n.xg-l,.xc-l{transition:y 1.2s ease,height 1.2s ease}\n.xp-gr circle{animation:xpfall 1.6s ease-in infinite}\n@keyframes xpfall{0%{transform:translateY(-30px);opacity:0}30%{opacity:1}100%{transform:translateY(70px);opacity:0}}\n.xp-lid{animation:xplid 2s ease-in-out infinite}\n@keyframes xplid{0%,100%{transform:translateY(0)}50%{transform:translateY(16px)}}\n.xp-drop{animation:xpdrop 1.2s ease-in infinite}\n@keyframes xpdrop{0%{transform:translateY(-6px);opacity:1}100%{transform:translateY(12px);opacity:0}}\n.xb circle,.xbb circle{animation:xbub 1.8s ease-in infinite}\n@keyframes xbub{0%{transform:translateY(0);opacity:0}20%{opacity:1}100%{transform:translateY(-80px);opacity:0}}\n.xbl{animation:xblp 2.4s ease-in-out infinite;transform-box:fill-box;transform-origin:50% 100%}\n@keyframes xblp{0%,100%{transform:rotate(0)}40%,60%{transform:rotate(-35deg) translateY(6px)}}\n.xbl-f{animation:xblf 3s ease-out forwards}\n@keyframes xblf{to{y:120px;height:56px}}\n.xt-s{animation:xtdrop 1.4s ease-in forwards}\n@keyframes xtdrop{to{transform:translateY(150px)}}\n.xt-y{animation:xtdrop 1.6s .3s ease-in forwards}\n.xt-cap{animation:xtcap .6s 1.8s ease-out both}\n@keyframes xtcap{from{transform:translateY(-20px);opacity:0}to{transform:translateY(0);opacity:1}}\n.xg-n{transform-origin:245px 110px;animation:xgn 2.4s ease-out forwards}\n@keyframes xgn{from{transform:rotate(-100deg)}to{transform:rotate(70deg)}}\n.xr-b{transform-origin:160px 100px;animation:xrb 2.6s ease-in-out forwards}\n@keyframes xrb{from{transform:rotate(-45deg)}to{transform:rotate(180deg)}}\n.xr-l{animation:xrl 2.6s ease-in forwards}\n@keyframes xrl{from{transform:translateY(0)}to{transform:translateY(-110px)}}\n.xr-ice{animation:xrice 1.4s 2.8s ease-out both}\n@keyframes xrice{from{transform:translateY(-10px);opacity:0}40%{opacity:1}to{transform:translateY(30px);opacity:0}}\n.xd-d{animation:xdd 1.4s ease-in forwards}\n@keyframes xdd{to{transform:translateY(120px);opacity:.3}}\n.xd-c{animation:xdc .8s 1.5s ease-out both}\n@keyframes xdc{from{transform:translateY(-30px);opacity:0}to{transform:translateY(0);opacity:1}}\n.xg-dr circle{animation:xgdr 1.5s ease-in infinite}\n@keyframes xgdr{from{transform:translateY(0);opacity:1}to{transform:translateY(60px);opacity:0}}\n.xg-pour{animation:xfade2 1.6s ease both}\n@keyframes xfade2{0%{opacity:0}30%{opacity:1}100%{opacity:0}}\n.xc-w path{animation:xcw 2.4s ease-in-out infinite}\n@keyframes xcw{0%{transform:translateY(10px);opacity:0}40%{opacity:.8}100%{transform:translateY(-20px);opacity:0}}\n.xcv{stroke-dasharray:900;stroke-dashoffset:900;animation:xcv 2.2s ease forwards}\n@keyframes xcv{to{stroke-dashoffset:0}}\n@media (prefers-reduced-motion: reduce){.xva *{animation:none!important;transition:none!important}.xcv{stroke-dashoffset:0}}\nhtml.xwlight .xva,html.xwlight .xvst{color:#EDE6D6}\n";document.head.appendChild(st);

 /* ---------- YouTube（點了才載入） ---------- */
 function yt(v,opt){opt=opt||{};var s=opt.start||0;
  var h='<div class="xvy" data-v="'+E(v.id)+'" data-s="'+s+'"><button type="button" class="xvyp" aria-label="播放影片：'+E(v.t)+'">'+
   '<img loading="lazy" decoding="async" alt="" src="https://i.ytimg.com/vi/'+E(v.id)+'/hqdefault.jpg">'+
   '<span class="xvyb"><svg viewBox="0 0 68 48" width="56" height="40"><path d="M66.5 7.7a8.5 8.5 0 0 0-6-6C55.2.4 34 .4 34 .4S12.8.4 7.5 1.7a8.5 8.5 0 0 0-6 6C.2 13 .2 24 .2 24s0 11 1.3 16.3a8.5 8.5 0 0 0 6 6C12.8 47.6 34 47.6 34 47.6s21.2 0 26.5-1.3a8.5 8.5 0 0 0 6-6C67.8 35 67.8 24 67.8 24s0-11-1.3-16.3z" fill="#C9A45C"/><path d="M27 34V14l18 10z" fill="#17120B"/></svg></span>'+
   (s?'<span class="xvyt">從 '+mmss(s)+' 開始</span>':'')+'<span class="xvyl">'+mmss(v.len)+'</span></button></div>';
  return h;}
 function play(box,s){var v=box.getAttribute('data-v');if(s==null)s=+box.getAttribute('data-s')||0;
  box.innerHTML='<iframe src="https://www.youtube-nocookie.com/embed/'+encodeURIComponent(v)+'?autoplay=1&rel=0&playsinline=1&start='+(s|0)+'" title="YouTube" allow="autoplay; encrypted-media; picture-in-picture; fullscreen" allowfullscreen></iframe>';
  box.classList.add('on');seenSet('v:'+v);}
 document.addEventListener('click',function(e){var t=e.target;if(!t.closest)return;
  var b=t.closest('.xvyp');if(b){e.preventDefault();play(b.parentNode);return;}
  var c=t.closest('.xvc[data-s]');if(c){e.preventDefault();var w=c.closest('.xvv');var box=w&&w.querySelector('.xvy');if(box){play(box,+c.getAttribute('data-s'));box.scrollIntoView({block:'nearest',behavior:'smooth'});}return;}
 },true);
 function vcard(v,o){o=o||{};var seen=seenGet()['v:'+v.id];
  var ch=(v.chaps||[]).map(function(c){return '<button type="button" class="xvc" data-s="'+c[0]+'">'+mmss(c[0])+' '+E(c[1])+'</button>';}).join('');
  return '<div class="xvv" data-xwns>'+yt(v,{start:o.start||0})+
   '<div class="xvm"><b class="xvt">'+E(v.t)+'</b><span class="xvi">'+E(v.ch)+'・'+E(v.date)+'・'+mmss(v.len)+(v.en?'・英文（可開中文自動字幕）':'')+
   '<i class="xvseen'+(seen?' on':'')+'" data-xvseen="v:'+E(v.id)+'">看過</i></span>'+
   (o.note?'<p class="xvn">'+(o.tag?'<em class="xvtag'+(o.tag==='本款'?' me':'')+'">'+E(o.tag)+'</em>':'')+E(o.note)+'</p>':'')+
   (o.nosum?'':'<p class="xvs">'+E(v.sum)+'</p>')+
   (ch?'<div class="xvcs"><span>跳到：</span>'+ch+'</div>':'')+
   '<a class="xvyt2" href="https://www.youtube.com/watch?v='+E(v.id)+(o.start?'&t='+o.start+'s':'')+'" target="_blank" rel="noopener">到 YouTube 看</a></div></div>';}

