 var KB=[];D.A.forEach(function(a){if(a.kb&&a.kb[0]===SITE)KB.push({k:a.kb[1],h:a.kb[2],a:a.id});});
 D.V.forEach(function(v,i){(v.kb||[]).forEach(function(k){if(k[0]===SITE)KB.push({k:k[1],h:k[2],v:i});});});
 function kb(){var todo=0;KB.forEach(function(x){if(x.ok)return;todo++;var ch=document.querySelector('.kbchap[data-kb="'+x.k+'"]');if(!ch)return;
   var hs=ch.querySelectorAll('h3');var h=null;for(var j=0;j<hs.length;j++){if((hs[j].textContent||'').indexOf(x.h)>=0){h=hs[j];break;}}if(!h)return;
   var w=h.parentNode.querySelector(':scope > .xvkb[data-h="'+x.h+'"]');
   if(!w){w=document.createElement('div');w.className='xvkb';w.setAttribute('data-h',x.h);w.setAttribute('data-xwns','');h.parentNode.insertBefore(w,h.nextSibling);}
   if(x.a){var t=document.createElement('div');t.innerHTML=abox(ABY[x.a]);w.insertBefore(t.firstChild,w.firstChild);initA(w.querySelector('.xva[data-a="'+x.a+'"]'));}
   else{var t2=document.createElement('div');t2.innerHTML='<div class="xvkbv"><span class="xvak">教學影片 VIDEO</span>'+vcard(D.V[x.v],{})+'</div>';w.appendChild(t2.firstChild);}
   x.ok=1;todo--;});return todo;}

 window.__xwVidPage=function(root,opt){root.innerHTML='';return {D:D,vcard:vcard,abox:abox,initA:initA,seen:seenGet,mmss:mmss,plink:plink,E:E};};

 function go(){if(window.__xwVidNoAuto)return;
  var L=document.getElementById('list');
  if(L){var ids=Object.keys(D.P),pend=0;function scan(){pend=0;ids.forEach(function(id){card(document.getElementById(id));});}
   scan();new MutationObserver(function(){if(!pend){pend=1;setTimeout(scan,300);}}).observe(L,{childList:true,subtree:true});}
  if(KB.length){kb();var iv=setInterval(function(){if(!KB.some(function(x){return !x.ok;})){clearInterval(iv);return;}kb();},2000);}
 }
